// bind lowers one row onto the runtime check type, against the run's own
// fixture — which is what lets a row's body draw what the run draws.
func (c TxWithRetryCheck) bind(
	fx TxWithRetryFixture,
) (suite.Check[TxWithRetry], error) {
	out := suite.Check[TxWithRetry]{
		Claim: c.Claim, Class: c.Class, Needs: c.Needs,
	}
	if out.Class == "" {
		out.Class = suite.ClassHandWritten
	}

	var err error
	bodies := 0
	if c.Run != nil {
		bodies++
		if out.ID, err = suite.RowID("Run", c.Method, c.Name, txWithRetryMethods); err != nil {
			return out, err
		}
		run := c.Run
		out.Run = func(tb testing.TB, s TxWithRetry) {
			run(tb, s, fx)
		}
	}
	if c.RunWith != nil {
		bodies++
		out.ID = suite.HandRowID(c.Name)
		rw := c.RunWith
		out.RunWith = func(tb testing.TB, sub TxWithRetrySubject) {
			rw(tb, sub, fx)
		}
	}
	if err := suite.OneBody(c.Name, bodies, "Run, RunWith"); err != nil {
		return out, err
	}
	if c.Method != "" && c.Run == nil {
		return out, fmt.Errorf(
			"check %q sets Method, but its body fixes its own scope; drop Method", c.Name)
	}
	if out.Falsifiable, err = suite.Falsify(c.Name, c.ProvenBy != nil, c.Argued); err != nil {
		return out, err
	}
	return out, nil
}

// RunTxWithRetry runs every check — generated and yours — against every
// harness.
//
//	RunTxWithRetry(t,
//		TxWithRetryHarness[*InMemory]{Name: "in-memory", New: NewInMemory},
//		TxWithRetrySuite.Without(TxWithRetrySuite.Checks.Begin.Smoke()),
//	)
func RunTxWithRetry(
	t *testing.T, opts ...TxWithRetryRunOpt,
) {
	t.Helper()
	var rc txWithRetryRunConfig
	for _, o := range opts {
		o.applyTo(&rc)
	}
	fx := txWithRetryNewFixture()
	for _, row := range rc.rows {
		rc.AddCheck(row.bind(fx))
	}
	// Between folding and running: a misused run reports every fix it
	// needs and executes nothing, rather than reporting one and leaving
	// the rest to be found a cycle at a time.
	rc.Fail(t, "RunTxWithRetry")
	suite.Run(t,
		txWithRetrySuite().With(rc.Extra...).Without(rc.Drops...),
		rc.Subjects...)
}

// ProveTxWithRetry drives each of your rows against the defect it names.
//
// A row with no ProvenBy is not skipped — it is held to saying why
// through Argued. The parity gate refuses a Proven claim with no
// evidence and evidence for a claim nobody made, in both directions, so
// this is where "proven able to fail" stops being prose.
func ProveTxWithRetry(
	t *testing.T, checks TxWithRetryChecks,
) {
	t.Helper()
	// The RUN's config, not the derived one: a check proven at default
	// pools carries no evidence about the pools a run actually uses.
	fx := txWithRetryNewFixture()
	bound := make([]suite.Check[TxWithRetry], 0, len(checks))
	defects := prove.Defects[TxWithRetry]{}
	for _, row := range checks {
		bd, err := row.bind(fx)
		if err != nil {
			t.Fatalf("ProveTxWithRetry: %v", err)
		}
		bound = append(bound, bd)
		if row.ProvenBy == nil {
			continue
		}
		sub, err := row.ProvenBy.Subject()
		if err != nil {
			t.Fatalf("ProveTxWithRetry: check %q: defect: %v", bd.ID, err)
		}
		defects[bd.ID] = prove.Defect[TxWithRetry]{
			Subject: sub, Reason: row.ProvenReason,
		}
	}
	prove.All(t, bound, defects)
}

